file.contenuto:
extends Node2D

const SCREEN_WIDTH: float = 800.0
const SCREEN_HEIGHT: float = 600.0
const PLAYER_SPEED: float = 350.0
const SPAWN_INTERVAL: float = 0.6

var meteors: Array[Meteor] = []
var spawn_timer: float = 0.0

@onready var player: Sprite2D = $Player


func _process(delta: float) -> void:
	_move_player(delta)
	_handle_spawning(delta)
	_cleanup_meteors()


func _move_player(delta: float) -> void:
	var direction := Vector2.ZERO
	if Input.is_action_pressed("move_left"):
		direction.x -= 1.0
	if Input.is_action_pressed("move_right"):
		direction.x += 1.0
	if Input.is_action_pressed("move_up"):
		direction.y -= 1.0
	if Input.is_action_pressed("move_down"):
		direction.y += 1.0

	if direction != Vector2.ZERO:
		direction = direction.normalized()
		player.position += direction * PLAYER_SPEED * delta

	player.position.x = clampf(player.position.x, 0.0, SCREEN_WIDTH)
	player.position.y = clampf(player.position.y, 0.0, SCREEN_HEIGHT)


func _handle_spawning(delta: float) -> void:
	spawn_timer += delta
	if spawn_timer >= SPAWN_INTERVAL:
		spawn_timer = 0.0
		_spawn_meteor()


func _spawn_meteor() -> void:
	var meteor := Meteor.new()
	var random_x := randf_range(20.0, SCREEN_WIDTH - 20.0)
	meteor.position = Vector2(random_x, -30.0)
	add_child(meteor)
	meteors.append(meteor)


func _cleanup_meteors() -> void:
	for i in range(meteors.size() - 1, -1, -1):
		var meteor := meteors[i]
		if meteor.position.y > SCREEN_HEIGHT + 40.0:
			meteors.remove_at(i)
			meteor.queue_free()
